/* Universal Resets & Base Styles */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b283a;
  --card-bg: #f9f5eb;
  --card-border: #4a4031;
  --primary: #c25953;
  --primary-hover: #a24641;
  --primary-active: #7e332f;
  --accent: #5b8a72;
  --accent-hover: #456b57;
  --text-main: #332d25;
  --text-muted: #6e6456;
  --surface: #ede5d5;
  --surface-alt: #ded3bf;
  --pixel-shadow: 4px 4px 0px #4a4031;
  --pixel-shadow-sm: 2px 2px 0px #4a4031;
}

body {
  font-family: 'Courier New', Courier, monospace, system-ui, -apple-system, sans-serif;
  background-color: var(--bg-color);
  background-image: 
    radial-gradient(#3a364d 15%, transparent 16%),
    radial-gradient(#3a364d 15%, transparent 16%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  color: var(--text-main);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

/* Main Centered Container */
.shelter-card {
  background-color: var(--card-bg);
  border: 4px solid var(--card-border);
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.45);
  border-radius: 4px;
  width: 100%;
  max-width: 820px;
  padding: 24px;
  margin: auto;
}

/* Header */
.shelter-header {
  text-align: center;
  border-bottom: 3px dashed var(--card-border);
  padding-bottom: 18px;
  margin-bottom: 24px;
}

.shelter-title {
  font-size: 2rem;
  color: var(--primary);
  letter-spacing: 1px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0px var(--surface-alt);
}

.shelter-subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  margin-top: 6px;
  font-weight: bold;
}

/* Stats Panel */
.stats-panel {
  display: flex;
  justify-content: space-around;
  gap: 16px;
  background-color: var(--surface);
  border: 3px solid var(--card-border);
  padding: 14px 16px;
  margin-bottom: 24px;
  box-shadow: var(--pixel-shadow-sm);
  flex-wrap: wrap;
}

.stat-box {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat-label {
  font-weight: bold;
  font-size: 1rem;
  color: var(--text-main);
}

.stat-badge {
  background-color: var(--card-border);
  color: #fff;
  font-weight: bold;
  font-size: 1.1rem;
  padding: 4px 14px;
  border-radius: 2px;
  min-width: 38px;
  text-align: center;
  box-shadow: 2px 2px 0px rgba(0, 0, 0, 0.25);
}

/* Filters */
.filter-section {
  margin-bottom: 24px;
}

.section-title {
  font-size: 1.25rem;
  color: var(--text-main);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-left: 6px solid var(--accent);
  padding-left: 8px;
}

.filter-group {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.filter-btn {
  background-color: var(--surface);
  color: var(--text-main);
  border: 2px solid var(--card-border);
  padding: 8px 18px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  box-shadow: var(--pixel-shadow-sm);
  transition: background-color 0.1s, transform 0.1s;
}

.filter-btn:hover {
  background-color: var(--surface-alt);
}

.filter-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.filter-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.filter-btn.active {
  background-color: var(--accent);
  color: #ffffff;
  border-color: var(--card-border);
}

/* Pet Grids */
.pets-section {
  margin-bottom: 28px;
}

.pets-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
  margin-top: 12px;
}

/* Pet Cards */
.pet-card {
  background-color: #fff;
  border: 3px solid var(--card-border);
  box-shadow: var(--pixel-shadow);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
}

.pet-card.adopted {
  background-color: #f3efe6;
  opacity: 0.95;
}

/* Pixel Avatar Canvas / Box */
.pet-avatar {
  width: 64px;
  height: 64px;
  background-color: var(--surface);
  border: 2px solid var(--card-border);
  margin-bottom: 12px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Pure CSS Pixel Characters */
.pixel-art {
  width: 8px;
  height: 8px;
  position: relative;
}

/* Cat pixel-art */
.pixel-cat {
  background-color: #d88137;
  box-shadow:
    -12px -8px 0 0 #d88137, 12px -8px 0 0 #d88137,
    -8px -4px 0 0 #d88137,  0px -4px 0 0 #d88137,  8px -4px 0 0 #d88137,
    -8px 0px 0 0 #2b283a,   0px 0px 0 0 #d88137,   8px 0px 0 0 #2b283a,
    -8px 4px 0 0 #d88137,   0px 4px 0 0 #e6a770,  8px 4px 0 0 #d88137,
    -4px 8px 0 0 #d88137,   4px 8px 0 0 #d88137;
}

/* Dog pixel-art */
.pixel-dog {
  background-color: #8c5b36;
  box-shadow:
    -12px -4px 0 0 #57371d, 12px -4px 0 0 #57371d,
    -8px -4px 0 0 #8c5b36,  0px -4px 0 0 #8c5b36,  8px -4px 0 0 #8c5b36,
    -8px 0px 0 0 #2b283a,   0px 0px 0 0 #8c5b36,   8px 0px 0 0 #2b283a,
    -8px 4px 0 0 #8c5b36,   0px 4px 0 0 #2b283a,   8px 4px 0 0 #8c5b36,
    -4px 8px 0 0 #e8c49e,   4px 8px 0 0 #e8c49e;
}

/* Bunny pixel-art */
.pixel-bunny {
  background-color: #e3ded8;
  box-shadow:
    -8px -12px 0 0 #e3ded8, 8px -12px 0 0 #e3ded8,
    -8px -8px 0 0 #e8a6a6,  8px -8px 0 0 #e8a6a6,
    -8px -4px 0 0 #e3ded8,  8px -4px 0 0 #e3ded8,
    -8px 0px 0 0 #2b283a,   0px 0px 0 0 #e3ded8,   8px 0px 0 0 #2b283a,
    -8px 4px 0 0 #e3ded8,   0px 4px 0 0 #e8a6a6,  8px 4px 0 0 #e3ded8,
    -4px 8px 0 0 #e3ded8,   4px 8px 0 0 #e3ded8;
}

.pet-name {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--text-main);
  margin-bottom: 4px;
}

.pet-meta {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.pet-species-badge {
  display: inline-block;
  background-color: var(--surface-alt);
  color: var(--text-main);
  font-size: 0.8rem;
  padding: 2px 8px;
  border-radius: 2px;
  margin-top: 4px;
  border: 1px solid var(--card-border);
}

.adopt-btn {
  margin-top: auto;
  width: 100%;
  background-color: var(--primary);
  color: #fff;
  border: 2px solid var(--card-border);
  padding: 8px 12px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  box-shadow: var(--pixel-shadow-sm);
  transition: background-color 0.1s, transform 0.1s;
}

.adopt-btn:hover {
  background-color: var(--primary-hover);
}

.adopt-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.adopt-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
  background-color: var(--primary-active);
}

.adopted-tag {
  margin-top: auto;
  width: 100%;
  text-align: center;
  background-color: var(--accent);
  color: #fff;
  padding: 6px 10px;
  font-weight: bold;
  font-size: 0.9rem;
  border: 2px solid var(--card-border);
  box-shadow: var(--pixel-shadow-sm);
}

.empty-msg {
  text-align: center;
  padding: 20px;
  background-color: var(--surface);
  border: 2px dashed var(--card-border);
  color: var(--text-muted);
  font-style: italic;
}

/* Responsive Tweaks */
@media (max-width: 480px) {
  body {
    padding: 12px 8px;
  }

  .shelter-card {
    padding: 16px;
  }

  .shelter-title {
    font-size: 1.5rem;
  }

  .stats-panel {
    flex-direction: column;
    align-items: stretch;
  }

  .stat-box {
    justify-content: space-between;
  }

  .pets-grid {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // 1. Initial Pet Data (6 built-in pets)
  const pets = [
    { id: 1, name: 'Mochi', species: 'Cat', age: '2 yrs', adopted: false },
    { id: 2, name: 'Barnaby', species: 'Dog', age: '4 yrs', adopted: false },
    { id: 3, name: 'Clover', species: 'Bunny', age: '1 yr', adopted: false },
    { id: 4, name: 'Pixel', species: 'Cat', age: '3 yrs', adopted: false },
    { id: 5, name: 'Rusty', species: 'Dog', age: '5 yrs', adopted: false },
    { id: 6, name: 'Pip', species: 'Bunny', age: '6 mos', adopted: false }
  ];

  // Current species filter: 'All' | 'Cat' | 'Dog' | 'Bunny'
  let activeFilter = 'All';

  // 2. DOM Elements
  const availableListEl = document.getElementById('available-list');
  const adoptedListEl = document.getElementById('adopted-list');
  const availableCountEl = document.getElementById('available-count');
  const adoptedCountEl = document.getElementById('adopted-count');
  const filterButtonsContainer = document.getElementById('filter-buttons');
  const noAvailableMsg = document.getElementById('no-available-msg');
  const noAdoptedMsg = document.getElementById('no-adopted-msg');

  // 3. Render Helpers
  function getPixelArtClass(species) {
    switch (species.toLowerCase()) {
      case 'cat':
        return 'pixel-cat';
      case 'dog':
        return 'pixel-dog';
      case 'bunny':
        return 'pixel-bunny';
      default:
        return '';
    }
  }

  function createPetCard(pet) {
    const card = document.createElement('article');
    card.className = `pet-card ${pet.adopted ? 'adopted' : ''}`;
    card.setAttribute('data-id', pet.id);
    card.setAttribute('aria-label', `${pet.name}, a ${pet.age} old ${pet.species}`);

    const avatar = document.createElement('div');
    avatar.className = 'pet-avatar';
    avatar.setAttribute('aria-hidden', 'true');

    const sprite = document.createElement('div');
    sprite.className = `pixel-art ${getPixelArtClass(pet.species)}`;
    avatar.appendChild(sprite);

    const nameHeading = document.createElement('h3');
    nameHeading.className = 'pet-name';
    nameHeading.textContent = pet.name;

    const metaInfo = document.createElement('p');
    metaInfo.className = 'pet-meta';
    metaInfo.innerHTML = `<span>Age: ${pet.age}</span><br><span class="pet-species-badge">${pet.species}</span>`;

    card.appendChild(avatar);
    card.appendChild(nameHeading);
    card.appendChild(metaInfo);

    if (!pet.adopted) {
      const adoptBtn = document.createElement('button');
      adoptBtn.type = 'button';
      adoptBtn.className = 'adopt-btn';
      adoptBtn.textContent = 'Adopt Me';
      adoptBtn.setAttribute('aria-label', `Adopt ${pet.name}`);
      adoptBtn.addEventListener('click', () => adoptPet(pet.id));
      card.appendChild(adoptBtn);
    } else {
      const adoptedTag = document.createElement('div');
      adoptedTag.className = 'adopted-tag';
      adoptedTag.textContent = 'Adopted ♥';
      card.appendChild(adoptedTag);
    }

    return card;
  }

  // 4. Update UI & Counts
  function render() {
    // Clear existing cards
    availableListEl.innerHTML = '';
    adoptedListEl.innerHTML = '';

    // Separate by status
    const availablePets = pets.filter(p => !p.adopted);
    const adoptedPets = pets.filter(p => p.adopted);

    // Filter available pets
    const filteredAvailable = availablePets.filter(p => {
      if (activeFilter === 'All') return true;
      return p.species.toLowerCase() === activeFilter.toLowerCase();
    });

    // Render Available Pets
    if (filteredAvailable.length === 0) {
      noAvailableMsg.hidden = false;
    } else {
      noAvailableMsg.hidden = true;
      filteredAvailable.forEach(pet => {
        availableListEl.appendChild(createPetCard(pet));
      });
    }

    // Render Adopted Pets
    if (adoptedPets.length === 0) {
      noAdoptedMsg.hidden = false;
    } else {
      noAdoptedMsg.hidden = true;
      adoptedPets.forEach(pet => {
        adoptedListEl.appendChild(createPetCard(pet));
      });
    }

    // Update Counters
    availableCountEl.textContent = availablePets.length;
    adoptedCountEl.textContent = adoptedPets.length;
  }

  // 5. Actions
  function adoptPet(id) {
    const targetPet = pets.find(p => p.id === id);
    if (targetPet && !targetPet.adopted) {
      targetPet.adopted = true;
      render();
    }
  }

  // 6. Filter Event Listeners
  filterButtonsContainer.addEventListener('click', (event) => {
    const button = event.target.closest('.filter-btn');
    if (!button) return;

    const species = button.getAttribute('data-species');
    if (!species || species === activeFilter) return;

    activeFilter = species;

    // Update active state on buttons
    const allButtons = filterButtonsContainer.querySelectorAll('.filter-btn');
    allButtons.forEach(btn => {
      const isActive = btn === button;
      btn.classList.toggle('active', isActive);
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });

    render();
  });

  // Initial Render
  render();
});
